import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"UI Revamp v0 — Inspiration References: Space Lifecycle","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/prd/ui-revamp-v0-refs-space-lifecycle.md","filePath":"architecture/prd/ui-revamp-v0-refs-space-lifecycle.md","lastUpdated":1780254295000}'),s={name:"architecture/prd/ui-revamp-v0-refs-space-lifecycle.md"};function n(i,e,c,d,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="ui-revamp-v0-—-inspiration-references-space-lifecycle" tabindex="-1">UI Revamp v0 — Inspiration References: Space Lifecycle <a class="header-anchor" href="#ui-revamp-v0-—-inspiration-references-space-lifecycle" aria-label="Permalink to &quot;UI Revamp v0 — Inspiration References: Space Lifecycle&quot;">​</a></h1><p>Companion to <a href="./ui-revamp-v0">ui-revamp-v0.md</a> and <a href="./ui-revamp-v0-refs">ui-revamp-v0-refs.md</a>. This pass covers the three flows the earlier refs doc deferred: creating a space (§4.1), configuring it (§4.2), and switching between spaces / documents (§4.8).</p><p>Same format as the original refs doc — references by refero UUID, no images embedded.</p><h2 id="_1-create-a-space-prd-§4-1" tabindex="-1">1. Create a space (PRD §4.1) <a class="header-anchor" href="#_1-create-a-space-prd-§4-1" aria-label="Permalink to &quot;1. Create a space (PRD §4.1)&quot;">​</a></h2><p>Trigger is the spaces-rail &quot;+&quot; button. PRD locks the flow to <strong>name → privacy (local / shared) → done</strong> as a single screen, not a wizard, with no assistant or bot setup at create time.</p><h3 id="borrow" tabindex="-1">Borrow <a class="header-anchor" href="#borrow" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Loom &quot;Create a new Space&quot;</strong> (<a href="https://refero.design/pages/e3c99d85-7919-40ca-95eb-0723f86cad78" target="_blank" rel="noreferrer">screen e3c99d85</a>). One centered modal with three labelled blocks (Name / Members / Privacy) and a single primary <code>Create Space</code> button alongside <code>Cancel</code>. The Privacy block is the exact pattern we want: two radio rows, <code>Open — Anyone at My Workspace can join</code> and <code>Closed — Only invited people can join</code>, each with a one-line subtext explaining the consequence. Map this 1:1 to our <code>Local — Only on this device</code> / <code>Shared — Visible to invited peers</code>. The descriptive subtext does the job of an info icon without one.</li><li><strong>Copy.ai &quot;Create Teamspace&quot;</strong> (<a href="https://refero.design/pages/60b58b03-3fd2-4004-af82-607b96097c79" target="_blank" rel="noreferrer">screen 60b58b03</a>). Same essential shape but tighter: name field at top, &quot;Team privacy&quot; header below, two radio rows <code>Public — Anyone can join</code> / <code>Private — Only people invited can join</code>. No members field at create time — defer membership to settings. This matches the PRD&#39;s &quot;no bots / no assistant at create&quot; — Copy.ai proves the trim works.</li><li><strong>Loom omission worth borrowing.</strong> Loom puts members in the create modal as a free-text &quot;Enter names&quot; field. We should <em>skip</em> this in v0: invitations require a peer-address paste, which is too heavy for an &quot;I&#39;m spinning up a quick space&quot; flow. Match Copy.ai&#39;s restraint.</li></ul><h3 id="avoid" tabindex="-1">Avoid <a class="header-anchor" href="#avoid" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Framer &quot;Create a new workspace&quot;</strong> (<a href="https://refero.design/pages/fc799b45-8c9f-4b8b-b89c-2388082c26bb" target="_blank" rel="noreferrer">screen fc799b45</a>, <a href="https://refero.design/pages/7976359d-ae0f-4b6a-89d3-e12a80b8eebe" target="_blank" rel="noreferrer">7976359d</a>). Step indicators at the top of a centered modal for a 2-step new-workspace flow. Two steps is one step too many for our case — the PRD says single screen, and the radio pair already covers privacy without a second page.</li><li><strong>Savee &quot;New Board&quot;</strong> (<a href="https://refero.design/pages/3395e1ce-741f-4ed9-b2ea-d65a7b64fbc7" target="_blank" rel="noreferrer">screen 3395e1ce</a>). Drop shadow on the modal, image-upload prompt inline. We don&#39;t have global shadows and don&#39;t want avatar/icon decisions at create time. The space icon can default to an initials chip (re-used from the rail) and be edited later in settings.</li><li><strong>Pitch &quot;Workspace name&quot; with avatar tile</strong> (visible in the background of <a href="https://refero.design/pages/80261480-1a56-490c-b070-bd06e5955638" target="_blank" rel="noreferrer">screen 80261480</a>). Same problem — gradient avatar tile at top of the create form invites the user to pick a color before they&#39;ve named the space. Defer all decoration.</li><li><strong>Pinterest-style multi-step &quot;Create a list&quot;</strong> flows reviewed across results — same wizard objection raised in the existing refs doc (§6). Reject again here.</li></ul><h3 id="synthesis-our-§4-1-create-space-modal" tabindex="-1">Synthesis: our §4.1 create-space modal <a class="header-anchor" href="#synthesis-our-§4-1-create-space-modal" aria-label="Permalink to &quot;Synthesis: our §4.1 create-space modal&quot;">​</a></h3><ul><li>One centered modal, no step indicator, no shadow (1px border + <code>base-200</code> background per §3 density rules).</li><li>Fields, top to bottom: <ul><li><strong>Name</strong> — single text input, autofocus, no placeholder beyond <code>Untitled space</code>.</li><li><strong>Privacy</strong> — two radio rows, <code>Local — Only on this device</code> / <code>Shared — Visible to invited peers</code>, each with a one-line subtext. Default to <code>Local</code> to match the local-first thesis.</li></ul></li><li>Footer: <code>Cancel</code> (ghost) + <code>Create space</code> (primary). No &quot;Create and open&quot; split — opening is the only success path.</li><li>Success: modal closes, the new space&#39;s icon appears in the rail with a brief outline pulse (1s) to confirm where it landed; the document column shows an empty-state placeholder (&quot;Add your first page&quot;). Not an onboarding tour.</li></ul><h2 id="_2-configure-a-space-prd-§4-2" tabindex="-1">2. Configure a space (PRD §4.2) <a class="header-anchor" href="#_2-configure-a-space-prd-§4-2" aria-label="Permalink to &quot;2. Configure a space (PRD §4.2)&quot;">​</a></h2><p>Tabs: General · Members · Assistant · Bots · Sharing · Danger. PRD constraint: at most one primary action per tab, no floating CTAs.</p><h3 id="borrow-1" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-1" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Linear workspace settings</strong> (<a href="https://refero.design/pages/79ca4f83-09ec-45a4-8905-6434488cfde7" target="_blank" rel="noreferrer">screen 79ca4f83</a>). Best end-to-end reference. Vertical left rail groups settings into <code>Account</code> / <code>Workspace</code> / <code>Features</code> / <code>Integrations</code>. Main column has sectioned cards (<code>Workspace</code>, <code>Time &amp; region</code>, <code>Danger zone</code>). Each section card has its own primary control: the field input is the action — auto-save on blur. <strong>Danger zone</strong> is a single row inside its own card: short label + sentence (&quot;Delete workspace / Schedule workspace to be permanently deleted&quot;) with the destructive action rendered as red link-styled text on the right, NOT a filled red button. This is exactly the restraint we want.</li><li><strong>Attio workspace settings</strong> (<a href="https://refero.design/pages/2f1fe188-d2bd-4928-8ace-055810c059ab" target="_blank" rel="noreferrer">screen 2f1fe188</a>). Same IA shape as Linear (left rail with <code>Account</code> / <code>Workspace</code> / <code>Data</code> / <code>Reports</code> groups). What it adds: the delete confirmation requires the user to <strong>type the workspace slug</strong> plus a &quot;Reason for deleting&quot; field, with the primary <code>Delete workspace</code> button disabled (pink/faded) until the slug matches. Borrow the slug-confirm gate verbatim for our <code>Danger</code> tab — it forces an intentional motion without a separate &quot;are you sure&quot; dialog.</li><li><strong>Pitch workspace settings</strong> (<a href="https://refero.design/pages/80261480-1a56-490c-b070-bd06e5955638" target="_blank" rel="noreferrer">screen 80261480</a>). Reference for the <strong>labelled &quot;Danger zone&quot; header in red</strong>, with the destructive action as a red filled button on the far right of a list row. The label &quot;Danger zone&quot; itself reads in red, which we should borrow — it&#39;s a stronger visual signal than the muted label Linear uses, and we don&#39;t lose anything from making this section&#39;s heading red since it appears only once on one tab.</li><li><strong>Factory.ai settings</strong> (<a href="https://refero.design/pages/7934f954-dd3d-4cd0-9807-8536c1fc607f" target="_blank" rel="noreferrer">screen 7934f954</a>). Reference for <strong>horizontal pill-tab IA</strong> instead of a left rail — <code>General · Integrations · Session · API Keys · Billing &amp; Usage</code> centered under a page title, with the active tab a filled pill. Below it: section cards (<code>Local Repositories</code>, <code>Factory Bridge</code>, <code>Remote Workspaces</code>) each with one primary action max (<code>edit</code>, toggle, <code>Create Workspace</code>). This is the layout closer to what our PRD asks for — our Space settings is <em>per-space</em>, not a global IA, so the breadcrumb is already the space; we don&#39;t need a second left rail. Use horizontal tabs.</li><li><strong>Kinhive settings</strong> (<a href="https://refero.design/pages/8307bc81-571f-4721-abe3-d43a05090f30" target="_blank" rel="noreferrer">screen 8307bc81</a>). Smaller-scale confirmation of the same idea: <code>Profile · Prompts · Account · Notifications · Billing</code> as a flat horizontal sub-nav under a single &quot;Settings&quot; h1, with the active tab underlined. Toggle rows auto-save inline — no Save button. Reinforces auto-save-on-blur as the v0 default.</li></ul><h3 id="decision-tabs-are-horizontal-not-a-left-rail" tabindex="-1">Decision: tabs are horizontal, not a left rail <a class="header-anchor" href="#decision-tabs-are-horizontal-not-a-left-rail" aria-label="Permalink to &quot;Decision: tabs are horizontal, not a left rail&quot;">​</a></h3><p>Linear and Attio use a left rail because their settings span account-level <em>and</em> workspace-level concerns — they need the grouping. Our Space settings is single-context (one space), so the left rail would just be a six-item vertical list eating ~200px to no purpose. Factory.ai and Kinhive both use a horizontal pill/underline tab strip for the same single-context case. Adopt horizontal tabs.</p><p>The PRD §4.2 wording (&quot;Tabs: General · Members · Assistant · Bots · Sharing · Danger&quot;) already implies horizontal — this just confirms it against references.</p><h3 id="save-model-auto-save-with-inline-error-no-global-save-button" tabindex="-1">Save model: auto-save with inline error, no global Save button <a class="header-anchor" href="#save-model-auto-save-with-inline-error-no-global-save-button" aria-label="Permalink to &quot;Save model: auto-save with inline error, no global Save button&quot;">​</a></h3><p>Linear and Kinhive both auto-save on blur. Toast-on-success is muted (or absent). Failures appear inline next to the field. Adopt this. The only explicit-save case is the <strong>Danger tab&#39;s <code>Delete space</code></strong> — destructive actions need the slug-confirm gate, never auto-save.</p><h3 id="avoid-1" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-1" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Cursor &quot;Privacy Settings&quot; modal-on-page</strong> (<a href="https://refero.design/pages/33c42658-b8ed-47d5-86bf-ab702d4b24a6" target="_blank" rel="noreferrer">screen 33c42658</a>). Settings page with a <em>modal on top of it</em> to edit a single setting. Two layers of chrome to flip one toggle. Our settings tabs are the surface; never spawn a modal to edit a field inside them.</li><li><strong>Doppler workplace settings</strong> (<a href="https://refero.design/pages/d8c20153-3f8c-4f2f-bf8b-b2a19897c1af" target="_blank" rel="noreferrer">screen d8c20153</a> — observed in dark variant <a href="https://refero.design/pages/075178eb-5aff-46fb-820d-7a63f9665f36" target="_blank" rel="noreferrer">075178eb</a>). One long unsectioned scroll of mixed concerns — Members and Plan and Billing and SCIM all stacked. The sectioning by <em>tab</em> the PRD calls for is exactly what&#39;s missing here. Don&#39;t regress to &quot;everything on one page&quot;.</li><li><strong>Per-section &quot;Save&quot; buttons.</strong> Rive&#39;s account settings (<a href="https://refero.design/pages/b9d7c9de-f4dd-43c5-9ce7-2df8572ea779" target="_blank" rel="noreferrer">screen b9d7c9de</a>) and several Doppler screens use per-card <code>Save</code> buttons. Multiplying primary buttons across the page is exactly the &quot;buttons everywhere&quot; anti-pattern the PRD rejects. Auto-save the input; if a section genuinely needs a multi-field atomic save (e.g. peer-address add — already handled in §4.4), the action goes at the bottom of that section&#39;s <em>form</em>, not on the section card chrome.</li><li><strong>Floating bottom-right CTAs</strong> (&quot;Save changes&quot; floating bar that slides in). Linear and Attio both demonstrate this is unnecessary if you auto-save. Skip it.</li><li><strong>Avatar/icon upload in the General tab as the first card.</strong> Pushes name/URL below the fold. Put identity fields (Name, URL/slug, optional icon) first in a single card, icon as a small inline edit chip not a giant upload tile.</li></ul><h3 id="synthesis-our-§4-2-tab-ia" tabindex="-1">Synthesis: our §4.2 tab IA <a class="header-anchor" href="#synthesis-our-§4-2-tab-ia" aria-label="Permalink to &quot;Synthesis: our §4.2 tab IA&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>Primary content</th><th>Single allowed action</th></tr></thead><tbody><tr><td>General</td><td>Name, icon (inline), description, locale</td><td>inputs auto-save on blur</td></tr><tr><td>Members</td><td>List of people in this space with role pill; one row per member</td><td><code>Invite member…</code> opens a peer-address paste form below the list (same form pattern as bot adding, §4.4)</td></tr><tr><td>Assistant</td><td>Configured ACP backends; default backend selector</td><td><code>Add backend…</code> opens inline form</td></tr><tr><td>Bots</td><td>Locked from existing refs doc — Appwrite-style scoped cards</td><td><code>Add bot</code> (already specified)</td></tr><tr><td>Sharing</td><td>Per-space sharing toggles + link policy (read-only in v0 if no public sharing yet)</td><td><code>Generate share link</code> or auto-save toggles</td></tr><tr><td>Danger</td><td>Single section card titled <code>Danger zone</code> (red label) with two rows: <code>Leave space</code> (if not owner) and <code>Delete space</code></td><td><code>Delete space</code> triggers slug-confirm gate</td></tr></tbody></table><p>The Danger tab gets the only filled-red button in the entire settings surface, and only after the slug match.</p><h2 id="_3-switch-spaces-documents-prd-§4-8" tabindex="-1">3. Switch spaces / documents (PRD §4.8) <a class="header-anchor" href="#_3-switch-spaces-documents-prd-§4-8" aria-label="Permalink to &quot;3. Switch spaces / documents (PRD §4.8)&quot;">​</a></h2><p>Spaces rail is locked at 52px icons. Page tree lives inside the document column header as a breadcrumb + tree popover, not a third pane.</p><h3 id="borrow-2" tabindex="-1">Borrow <a class="header-anchor" href="#borrow-2" aria-label="Permalink to &quot;Borrow&quot;">​</a></h3><ul><li><strong>Cursor agents search/empty-state pattern</strong> (<a href="https://refero.design/pages/f955f80d-b216-42ee-ad4e-7f32f7140d14" target="_blank" rel="noreferrer">screen f955f80d</a>). Compact in-page search with a sticky left rail of <code>Today</code> / <code>Yesterday</code> recents, and keyboard-hint chips at the bottom of the popover (<code>↑↓ Navigate</code>, <code>↵ Open</code>, <code>Esc Close</code>). This is exactly the visual treatment we want for our switcher popover — sectioned by recency, keyboard chips visible, minimal chrome. Borrow the chip strip verbatim; it teaches the keyboard model without a tooltip.</li><li><strong>Slite search modal</strong> (<a href="https://refero.design/pages/af63af6f-e300-4eed-b960-ec6d0db5fbff" target="_blank" rel="noreferrer">screen af63af6f</a>). Centered floating modal: search input at top with a scope dropdown (<code>In all channels</code>) on the right, then a single-column result list grouped by type. Borrow the scope dropdown idea: our switcher should let the user <em>scope to the active space</em> by default and expand to <code>All spaces</code> with one keystroke / one click. Most switches are within-space (jumping between docs); cross-space is the minority case.</li><li><strong>Kitchen.co folder breadcrumb</strong> (<a href="https://refero.design/pages/c9f69780-d305-41b2-a264-ea202f809333" target="_blank" rel="noreferrer">screen c9f69780</a>). The document column header carries a breadcrumb <code>Refero / Bucket 37 / Boring …</code>, and the sidebar carries the tree. We&#39;re folding both into the header: clicking the current page name in the breadcrumb opens the tree popover anchored beneath it. Borrow the visual chevron-separated breadcrumb but <strong>drop the persistent tree pane</strong> — popover only.</li><li><strong>Skiff document breadcrumb</strong> (<a href="https://refero.design/pages/d24a9003-e2b8-442c-b992-67d74a84a797" target="_blank" rel="noreferrer">screen d24a9003</a>). Reference for a breadcrumb that includes a trailing <strong>doc actions button</strong> (<code>⋯</code>) right next to it, so the doc header carries: <code>breadcrumb</code> + <code>title</code> + <code>actions</code> in one row. Adopt this so the header stays a single row even with the tree-popover trigger included.</li><li><strong>Factory.ai workspace picker</strong> (<a href="https://refero.design/pages/8bcd2e73-62e0-40c9-8b5b-56267986aef4" target="_blank" rel="noreferrer">screen 8bcd2e73</a>). A spaces-style picker that lists workspaces with status pills. Confirms the spaces rail&#39;s secondary affordance: long-press / right-click on a rail icon could surface a popover with the space name + status + &quot;Open settings&quot;, matching the rail-icon-as-primary-control model. Borrow the status pill treatment (small colored dot inline with the name).</li></ul><h3 id="synthesis-our-§4-8-surfaces" tabindex="-1">Synthesis: our §4.8 surfaces <a class="header-anchor" href="#synthesis-our-§4-8-surfaces" aria-label="Permalink to &quot;Synthesis: our §4.8 surfaces&quot;">​</a></h3><p>Three switching surfaces, each scoped to a clear job:</p><ol><li><strong>Spaces rail (52px, always visible).</strong> Click icon → switch space. Hover → tooltip with name. Right-click / long-press → popover with name + &quot;Settings&quot; + &quot;Leave&quot;. No labels in the rail itself.</li><li><strong>Breadcrumb tree popover (in document column header).</strong> Click the breadcrumb&#39;s last segment (current page) → opens a popover with: <ul><li>Search input at top.</li><li><strong>Recent</strong> section (5 docs in this space).</li><li><strong>Starred</strong> section (if any in this space).</li><li><strong>All pages</strong> as a collapsible tree, rendered via <a href="https://www.npmjs.com/package/react-complex-tree" target="_blank" rel="noreferrer"><code>react-complex-tree</code></a>. That library gives us keyboard navigation, drag-and-drop reordering, and virtualization for large trees out of the box — we avoid reinventing those for a popover that needs all three.</li><li>Footer keyboard-hint chips: <code>↑↓ Navigate</code>, <code>↵ Open</code>, <code>⌘↵ Open in new tab</code>, <code>Esc Close</code>.</li><li>Default scope is current space; one keystroke (e.g. <code>Tab</code>) widens to all spaces, surfacing the spaces rail&#39;s icons as section headers in the popover.</li></ul></li><li><strong>Command palette (⌘K, modal).</strong> Cross-cutting: jump to any space, any doc, any space-setting tab, run any slash command. Sections in priority order: <strong>Recent docs (any space)</strong> → <strong>Spaces</strong> → <strong>Documents</strong> → <strong>Commands</strong>. Keyboard-driven; closes on Esc. Same chip-strip footer as the popover.</li></ol><h3 id="avoid-2" tabindex="-1">Avoid <a class="header-anchor" href="#avoid-2" aria-label="Permalink to &quot;Avoid&quot;">​</a></h3><ul><li><strong>Three-pane Notion-style layout</strong> (spaces rail + tree column + editor). The PRD already rejects this — the breadcrumb popover replaces the tree column. Note here so the lock pass doesn&#39;t reintroduce it under &quot;but for discoverability we need a tree visible&quot;.</li><li><strong>Rive workspaces dropdown</strong> (<a href="https://refero.design/pages/15e676fa-46bc-4c4f-be4b-dbc490616a84" target="_blank" rel="noreferrer">screen 15e676fa</a>). Putting workspace switching in a top-bar dropdown labelled &quot;Workspaces&quot;. We have a dedicated rail; don&#39;t duplicate the affordance into a header dropdown.</li><li><strong>GitHub-style branch/repo combo selector glued to a page header.</strong> Same duplication problem; the rail owns space switching.</li><li><strong>Big &quot;Recent files&quot; modal that pretends to be a command palette but only does files</strong> (we&#39;ve seen this in several entries). Our palette has to do <em>commands</em> too, not just navigate; designing the surface as just-a-file-finder would force a separate command UI later. Build it as a palette from day one.</li><li><strong>Modal switcher with no keyboard hints visible</strong> (e.g. Mailchimp search <a href="https://refero.design/pages/ae4eb950-c449-4309-8563-8fc7d605176b" target="_blank" rel="noreferrer">ae4eb950</a> reads like a giant search field with no affordance for arrow-key behavior). Always show the chip strip — the v0 user is on a keyboard.</li><li><strong>Persistent collapsed tree-as-strip on the document column edge</strong> (Notion&#39;s &quot;side peek&quot;). The popover dismisses on selection or Esc; do not leave a half-visible tree pinned, which would steal the space the editor needs.</li></ul><h2 id="_4-pattern-locks-recommendations-for-adr-0005" tabindex="-1">4. Pattern locks (recommendations for ADR-0005) <a class="header-anchor" href="#_4-pattern-locks-recommendations-for-adr-0005" aria-label="Permalink to &quot;4. Pattern locks (recommendations for ADR-0005)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>PRD ref</th><th>Pattern locked from refs</th><th>Reference</th></tr></thead><tbody><tr><td>§4.1 create modal</td><td>Single centered modal, three blocks (Name / Privacy / footer). Privacy is two radio rows with one-line subtexts (<code>Local</code> / <code>Shared</code>). No avatar, no members, no step indicator</td><td>Loom e3c99d85, Copy.ai 60b58b03</td></tr><tr><td>§4.1 success</td><td>Modal closes; new icon appears in rail with brief outline pulse; document column shows empty placeholder. No onboarding tour</td><td>(synthesis)</td></tr><tr><td>§4.2 IA</td><td>Horizontal pill/underline tabs under page title, one tab = one screen of sectioned cards. No left rail (single-context)</td><td>Factory.ai 7934f954, Kinhive 8307bc81</td></tr><tr><td>§4.2 save model</td><td>Auto-save on blur; failures inline; no global Save button; per-section Save buttons banned</td><td>Linear 79ca4f83, Kinhive 8307bc81</td></tr><tr><td>§4.2 danger zone</td><td>Red-labelled &quot;Danger zone&quot; section card. <code>Delete space</code> triggers an inline slug-confirm form (type the space slug + optional reason); destructive button stays disabled until the slug matches</td><td>Linear 79ca4f83, Attio 2f1fe188, Pitch 80261480</td></tr><tr><td>§4.8 rail</td><td>52px icon-only rail; right-click / long-press surfaces a contextual popover with name + Settings + Leave</td><td>(locked already in original refs); status-dot treatment from Factory.ai 8bcd2e73</td></tr><tr><td>§4.8 tree popover</td><td>Anchored under the last breadcrumb segment in the document column header. Sections: Search / Recent / Starred / All pages. Footer chip strip teaches keyboard shortcuts. Scope defaults to current space; Tab widens to all spaces</td><td>Cursor f955f80d, Slite af63af6f, Kitchen.co c9f69780</td></tr><tr><td>§4.8 command palette</td><td>⌘K modal. Sections: Recent docs (any space) → Spaces → Documents → Commands. Same chip-strip footer as the tree popover</td><td>Cursor f955f80d</td></tr></tbody></table><h2 id="_5-open-follow-up" tabindex="-1">5. Open follow-up <a class="header-anchor" href="#_5-open-follow-up" aria-label="Permalink to &quot;5. Open follow-up&quot;">​</a></h2><ul><li><strong>Multi-window space context.</strong> When a typing popup or future popup window is open, which space + document does the rail in <em>that</em> window represent? Refero gave us no useful reference for sibling-window context indicators. Likely answer: popup windows have no rail, no breadcrumb — they&#39;re scoped to a single resource and dismiss on close. Confirm in the lock pass.</li><li><strong>Owner-vs-non-owner Danger tab.</strong> Owner sees <code>Delete space</code>; non-owner sees <code>Leave space</code>. Linear and Attio both gate by role, but neither shows a clean reference for <em>both rows appearing on one tab</em>. We may want a single <code>Danger</code> row that renders contextually (delete or leave) rather than two rows where one is always disabled.</li><li><strong>Shared-space membership at create time.</strong> PRD §4.1 says no invites at create. Loom puts them in the modal anyway. We&#39;re skipping them, but the empty-state placeholder in the new space should surface a single inline <code>Invite peer</code> chip pointing at the Members tab — Refero references don&#39;t cover this exact moment well, so it&#39;s our call.</li><li><strong>Tree popover under deep hierarchies.</strong> If a space has 500 pages, &quot;All pages&quot; as a tree inside a popover may be too heavy. Slite handles it with channel scope + search; we may want a &quot;virtualized tree only beyond depth N&quot; rule. No Refero answer here.</li></ul><hr><p><em>Next: fold the §4.1 modal shape and §4.2 horizontal-tab + auto-save + slug-confirm into the PRD draft, then promote the pattern-lock rows into ADR-0005 alongside the original refs doc&#39;s locks.</em></p>',40)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
